class Graph:
    def __init__(self, data=None):
        self.nodes = []
        self.edges = []
        self.attrs = {}

        if data is None:
            return

        if not isinstance(data, list):
            raise TypeError("Graph data malformed")

        for item in data:
            if not isinstance(item, (tuple, list)) or len(item) < 3:
                raise TypeError("Graph item incomplete")

            item_type = item[0]
            if item_type == NODE:
                if len(item) != 3:
                    raise ValueError("Node is malformed")
                self.nodes.append(Node(item[1], item[2]))
            elif item_type == EDGE:
                if len(item) != 4:
                    raise ValueError("Edge is malformed")
                self.edges.append(Edge(item[1], item[2], item[3]))
            elif item_type == ATTR:
                if len(item) != 3:
                    raise ValueError("Attribute is malformed")
                self.attrs[item[1]] = item[2]
            else:
                raise ValueError("Unknown item")

    def to_dot(self):
        lines = ["graph {"]

        for key, value in self.attrs.items():
            lines.append(f'\tgraph [{key}="{value}"]')

        for node in self.nodes:
            attrs = ", ".join(f'{k}="{v}"' for k, v in node.attrs.items())
            if attrs:
                lines.append(f"\t{node.name} [{attrs}]")
            else:
                lines.append(f"\t{node.name}")

        for edge in self.edges:
            attrs = ", ".join(f'{k}="{v}"' for k, v in edge.attrs.items())
            if attrs:
                lines.append(f"\t{edge.src} -- {edge.dst} [{attrs}]")
            else:
                lines.append(f"\t{edge.src} -- {edge.dst}")

        lines.append("}")
        return "\n".join(lines)

